public class Study{public static Object create(long n,long d){return new Fraction(n,d);}public static long numerator(Object a){return ((Fraction)a).numerator();}public static long denominator(Object a){return ((Fraction)a).denominator();}public static Object calculate(Object a,Object b,int op){Fraction x=(Fraction)a,y=(Fraction)b;return switch(op){case 0->x.add(y);case 1->x.subtract(y);case 2->x.multiply(y);default->x.divide(y);};}}
